package com.paytrace.common; import java.nio.charset.StandardCharsets; import java.security.*; public final class Hashing { private Hashing(){} public static String sha256(String value){try{var bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));var out=new StringBuilder();for(byte b:bytes)out.append(String.format("%02x",b));return out.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
